import{_ as l,o as e,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"帳單退款說明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/10-bill-refund-guide.md","filePath":"v1/zh-HK/guide/10-bill-refund-guide.md"}'),t={name:"v1/zh-HK/guide/10-bill-refund-guide.md"};function o(h,a,d,n,u,s){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="帳單退款說明" tabindex="-1">帳單退款說明 <a class="header-anchor" href="#帳單退款說明" aria-label="Permalink to &quot;帳單退款說明&quot;">​</a></h1><h2 id="_1-這是什麼功能" tabindex="-1">1. 這是什麼功能 <a class="header-anchor" href="#_1-這是什麼功能" aria-label="Permalink to &quot;1. 這是什麼功能&quot;">​</a></h2><p>「退款」用來記錄一筆帳單發生退款後的資金變化，並自動抵銷統計上的金額影響。</p><p>系統的做法是：在原帳單的基礎上，新增一筆「金額為負數」的退款記錄。</p><ul><li>原帳單是支出：退款記錄同樣是「支出」，但金額為負數，用來抵銷原支出</li><li>原帳單是收入：退款記錄同樣是「收入」，但金額為負數，用來抵銷原收入</li></ul><p>同時，退款記錄會自動加上「退款」標籤，方便之後篩選與核對。</p><h2 id="_2-適用場景" tabindex="-1">2. 適用場景 <a class="header-anchor" href="#_2-適用場景" aria-label="Permalink to &quot;2. 適用場景&quot;">​</a></h2><ul><li>購物退款、退貨退款</li><li>帳單部分退款（只退一部分金額）</li><li>收入回退（例如轉帳撤回、收款退回）</li></ul><h2 id="_3-如何使用" tabindex="-1">3. 如何使用 <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用&quot;">​</a></h2><ol><li>進入「帳單列表」找到要退款的帳單</li><li>對該帳單左滑，選擇「退款」</li><li>在退款頁面中設定： <ul><li>金額：預設等於原帳單金額，可改為部分退款金額</li><li>時間：預設今天，可改為實際退款發生的日期</li><li>標籤：預設沿用原帳單的標籤，並自動追加「退款」標籤</li><li>備註：可選，用作補充說明</li></ul></li><li>點選「確定/完成」儲存</li></ol><p>儲存後，列表會新增一筆退款記錄，用來抵銷對應的金額影響。</p><h2 id="_4-使用規則與注意事項" tabindex="-1">4. 使用規則與注意事項 <a class="header-anchor" href="#_4-使用規則與注意事項" aria-label="Permalink to &quot;4. 使用規則與注意事項&quot;">​</a></h2><ul><li>退款金額建議填寫「實際退回的金額」，不需要手動加負號。</li><li>支出退款與收入退款都會以「負數金額」的方式記錄，因此在統計中會自動抵銷。</li><li>支援多次退款：同一筆帳單若分多次退款，可以重複操作，每次會生成一筆退款記錄。</li><li>若你刪除了退款記錄，對應的抵銷效果也會消失（統計會回到未退款狀態）。</li></ul><h2 id="_5-常見問題" tabindex="-1">5. 常見問題 <a class="header-anchor" href="#_5-常見問題" aria-label="Permalink to &quot;5. 常見問題&quot;">​</a></h2><h3 id="q1-部分退款要怎麼記" tabindex="-1">Q1：部分退款要怎麼記？ <a class="header-anchor" href="#q1-部分退款要怎麼記" aria-label="Permalink to &quot;Q1：部分退款要怎麼記？&quot;">​</a></h3><p>在退款頁面把金額改成實際退款金額即可。你也可以多次退款，每次填各自的退款金額。</p><h3 id="q2-退款會影響原帳單嗎" tabindex="-1">Q2：退款會影響原帳單嗎？ <a class="header-anchor" href="#q2-退款會影響原帳單嗎" aria-label="Permalink to &quot;Q2：退款會影響原帳單嗎？&quot;">​</a></h3><p>原帳單本身不會被修改金額；退款是以「新增一筆退款記錄」的方式實作。這樣可以保留原始消費記錄，同時讓統計結果可解釋、可追溯。</p><h3 id="q3-怎麼快速找到所有退款" tabindex="-1">Q3：怎麼快速找到所有退款？ <a class="header-anchor" href="#q3-怎麼快速找到所有退款" aria-label="Permalink to &quot;Q3：怎麼快速找到所有退款？&quot;">​</a></h3><p>退款記錄會自動帶「退款」標籤，你可以在篩選/搜尋中按標籤查看。</p>',20)])])}const p=l(t,[["render",o]]);export{c as __pageData,p as default};
